input.sparql:
SELECT ?z ?ts ?lbl WHERE {
  ?z a brick:HVAC_Zone ; brick:hasLabel ?lbl .
  FILTER(?lbl IN ("Perimeter_mid_ZN_3","DataCenter_top_ZN_6")) .
  OPTIONAL { ?z ref:hasExternalReference ?ref ; ref:hasTimeseriesId ?ts . }
}

SELECT ?p ?lbl ?cls WHERE {
  ?p brick:hasLabel ?lbl .
  FILTER(?lbl IN ("Perimeter_mid_ZN_3","DataCenter_top_ZN_6")) .
  ?p a ?cls .
}

SELECT ?p ?lbl ?cls WHERE {
  ?p brick:hasLabel ?lbl .
  ?p a ?cls .
  FILTER(CONTAINS(?lbl, "ZN_3") || CONTAINS(?lbl, "ZN_6"))
}

SELECT ?z ?lbl WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?lbl .
} LIMIT 400

SELECT ?z ?t ?l ?ts WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?l .
  FILTER(CONTAINS(?l, "ZN_3") || CONTAINS(?l, "ZN_6"))
  OPTIONAL { ?z ref:hasTimeseriesId ?ts . }
} LIMIT 200

SELECT ?t (COUNT(*) AS ?n) WHERE {
  ?s a ?t .
} GROUP BY ?t

SELECT ?z ?l WHERE {
  ?z a brick:HVAC_Zone .
  ?z rdfs:label ?l .
} LIMIT 30

SELECT ?p ?ts WHERE {
  ?p a brick:Occupancy_Sensor .
  ?p brick:isPointOf ?z .
  ?z a brick:HVAC_Zone .
  ?z rdfs:label ?lbl .
  FILTER(?lbl IN ("Perimeter_mid_ZN_3","DataCenter_top_ZN_6")) .
  OPTIONAL { ?z ref:hasTimeseriesId ?ts . }
  ?p ref:hasTimeseriesId ?pts .
  BIND(CONCAT("P:",STR(?p)," L:",?lbl," TS:",STR(?pts)) AS ?ts)
}

SELECT ?p ?loc ?ts ?lblloc WHERE {
  ?p a brick:Occupancy_Sensor .
  OPTIONAL { ?p brick:isPointOf ?z . }
  ?p brick:hasLocation ?loc .
  ?loc rdfs:label ?lblloc .
  ?p ref:hasTimeseriesId ?ts .
  FILTER(CONTAINS(?lblloc, "ZN_3") || CONTAINS(?lblloc, "ZN_6"))
}

SELECT ?p ?t ?o WHERE {
  ?p a brick:Occupancy_Sensor .
  ?p ?t ?o .
  FILTER(?t != rdf:type)
} LIMIT 60
